-- Name: Priya Leisure pilgrim gap analysis - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH leisure_destids AS ( SELECT destid FROM (VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815),(247), (307614),(289873),(76480),(204358),(298723),(82558),(75103),(517),(265316),(231), (1529),(879),(217335),(1242),(71642),(93968),(74124),(142),(636),(1136),(520),(669), (1061),(77167),(275),(69526),(802),(196),(1528),(77530),(200347),(305974),(68747), (735),(84848),(197504),(216551),(68705),(1343),(80438),(427),(77687),(73533),(196096), (202212),(711),(78796),(489),(747),(93580),(466),(77705),(68871),(1148),(1459),(361), (471),(70983),(81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475),(74130),(215191), (84310),(1496),(403),(1141),(189),(133),(177),(1351),(70628),(74708),(66007),(198750), (663),(94877),(71756),(1128),(293),(534),(77093),(154),(1001),(70030),(576),(70429), (217),(960),(196420),(94782),(300439) ) AS t(destid) ), user_journeys AS ( SELECT rbuserid, srclocationid AS src, dstlocationid AS dst, CAST(from_iso8601_timestamp(dateofjourney) + INTERVAL '5' HOUR + INTERVAL '30' MINUTE AS DATE) AS travel_date, ROW_NUMBER() OVER w AS leg_seq FROM "neon_ind_event"."neon_ind_ticket" WHERE year >= '2025' AND countrycode = 'IND' AND rbuserid > 0 AND tin IS NOT NULL AND tin <> '' AND srclocationid <> dstlocationid AND CAST(from_iso8601_timestamp(dateofjourney) + INTERVAL '5' HOUR + INTERVAL '30' MINUTE AS DATE) BETWEEN DATE '2025-10-01' AND DATE '2025-11-15' WINDOW w AS (PARTITION BY rbuserid ORDER BY CAST(from_iso8601_timestamp(dateofjourney) + INTERVAL '5' HOUR + INTERVAL '30' MINUTE AS DATE), tin, srclocationid, dstlocationid) ), -- First leisure destination booking per user in October -- home = src of this leg (whatever city they departed from) first_legs AS ( SELECT rbuserid, src AS home, -- city they departed FROM to reach B dst AS B, travel_date AS trip_start, leg_seq AS first_leisure_leg_seq FROM ( SELECT rbuserid, src, dst, travel_date, leg_seq, ROW_NUMBER() OVER (PARTITION BY rbuserid ORDER BY travel_date, leg_seq) AS rn FROM user_journeys WHERE dst IN (SELECT destid FROM leisure_destids) AND travel_date BETWEEN DATE '2025-10-01' AND DATE '2025-10-31' ) WHERE rn = 1 ), -- All legs after the first leisure leg, within 15 days subsequent_legs AS ( SELECT j.rbuserid, j.src, j.dst, j.travel_date, j.leg_seq, f.home, f.B, f.trip_start, f.first_leisure_leg_seq, LAG(j.dst) OVER (PARTITION BY j.rbuserid ORDER BY j.leg_seq) AS prev_platform_dst FROM user_journeys j JOIN first_legs f ON j.rbuserid = f.rbuserid AND j.leg_seq > f.first_leisure_leg_seq -- ✅ relative to first leisure leg AND j.travel_date > f.trip_start AND j.travel_date <= f.trip_start + INTERVAL '15' DAY ), -- Gap detection: -- first leg after B: gap if src != B -- subsequent legs: gap if src != prev platform dst legs_with_gap AS ( SELECT *, CASE WHEN leg_seq = first_leisure_leg_seq + 1 AND src <> B THEN 1 WHEN leg_seq > first_leisure_leg_seq + 1 AND src <> prev_platform_dst THEN 1 ELSE 0 END AS has_gap_before FROM subsequent_legs ), first_return_home AS ( SELECT rbuserid, home, trip_start, MIN(leg_seq) AS first_return_leg_seq FROM legs_with_gap WHERE dst = home GROUP BY rbuserid, home, trip_start ), truncated_legs AS ( SELECT s.* FROM legs_with_gap s LEFT JOIN first_return_home r ON s.rbuserid = r.rbuserid AND s.home = r.home AND s.trip_start = r.trip_start WHERE s.leg_seq <= COALESCE(r.first_return_leg_seq, s.leg_seq) ), trip_classification AS ( SELECT f.rbuserid, f.B, f.trip_start, MAX(CASE WHEN t.dst = f.home THEN 1 ELSE 0 END) AS returned_home, COUNT(CASE WHEN t.dst <> f.home THEN 1 END) AS intermediate_stops, COUNT(t.leg_seq) AS total_subsequent_legs, SUM(COALESCE(t.has_gap_before, 0)) AS total_gaps FROM first_legs f LEFT JOIN truncated_legs t ON t.rbuserid = f.rbuserid AND t.home = f.home AND t.trip_start = f.trip_start GROUP BY f.rbuserid, f.B, f.trip_start ), trip_buckets AS ( SELECT rbuserid, B, CASE WHEN total_gaps = 0 AND returned_home = 1 AND intermediate_stops = 0 THEN 'A_B_A' WHEN total_gaps = 0 AND returned_home = 1 AND intermediate_stops = 1 THEN 'A_B_C_A' WHEN total_gaps = 0 AND returned_home = 1 AND intermediate_stops = 2 THEN 'A_B_C_D_A' WHEN total_gaps = 0 AND returned_home = 1 AND intermediate_stops = 3 THEN 'A_B_C_D_E_A' WHEN total_gaps = 0 AND returned_home = 1 AND intermediate_stops = 4 THEN 'A_B_C_D_E_F_A' WHEN total_gaps = 0 AND returned_home = 1 AND intermediate_stops = 5 THEN 'A_B_C_D_E_F_G_A' WHEN total_gaps = 0 AND returned_home = 1 AND intermediate_stops >= 6 THEN 'A_8plus_A' WHEN total_gaps = 0 AND returned_home = 0 AND total_subsequent_legs = 0 THEN 'A_B_no_subsequent' WHEN total_gaps = 0 AND returned_home = 0 AND intermediate_stops = 0 THEN 'A_B_no_return' WHEN total_gaps = 0 AND returned_home = 0 AND intermediate_stops >= 1 THEN 'A_B_Cplus_no_return' WHEN total_gaps = 1 AND returned_home = 1 THEN 'gap_1_returned' WHEN total_gaps = 1 AND returned_home = 0 THEN 'gap_1_no_return' WHEN total_gaps = 2 AND returned_home = 1 THEN 'gap_2_returned' WHEN total_gaps = 2 AND returned_home = 0 THEN 'gap_2_no_return' WHEN total_gaps >= 3 AND returned_home = 1 THEN 'gap_3plus_returned' WHEN total_gaps >= 3 AND returned_home = 0 THEN 'gap_3plus_no_return' ELSE 'uncategorised' END AS bucket FROM trip_classification ) SELECT B AS destid, -- Clean route buckets COUNT(DISTINCT CASE WHEN bucket = 'A_B_A' THEN rbuserid END) AS "A_B_A", COUNT(DISTINCT CASE WHEN bucket = 'A_B_C_A' THEN rbuserid END) AS "A_B_C_A", COUNT(DISTINCT CASE WHEN bucket = 'A_B_C_D_A' THEN rbuserid END) AS "A_B_C_D_A", COUNT(DISTINCT CASE WHEN bucket = 'A_B_C_D_E_A' THEN rbuserid END) AS "A_B_C_D_E_A", COUNT(DISTINCT CASE WHEN bucket = 'A_B_C_D_E_F_A' THEN rbuserid END) AS "A_B_C_D_E_F_A", COUNT(DISTINCT CASE WHEN bucket = 'A_B_C_D_E_F_G_A' THEN rbuserid END) AS "A_B_C_D_E_F_G_A", COUNT(DISTINCT CASE WHEN bucket = 'A_8plus_A' THEN rbuserid END) AS "A_8plus_A", COUNT(DISTINCT CASE WHEN bucket = 'A_B_no_subsequent' THEN rbuserid END) AS "A_B_no_subsequent", COUNT(DISTINCT CASE WHEN bucket = 'A_B_no_return' THEN rbuserid END) AS "A_B_no_return", COUNT(DISTINCT CASE WHEN bucket = 'A_B_Cplus_no_return' THEN rbuserid END) AS "A_B_Cplus_no_return", -- Gap buckets COUNT(DISTINCT CASE WHEN bucket = 'gap_1_returned' THEN rbuserid END) AS "gap_1_returned", COUNT(DISTINCT CASE WHEN bucket = 'gap_1_no_return' THEN rbuserid END) AS "gap_1_no_return", COUNT(DISTINCT CASE WHEN bucket = 'gap_2_returned' THEN rbuserid END) AS "gap_2_returned", COUNT(DISTINCT CASE WHEN bucket = 'gap_2_no_return' THEN rbuserid END) AS "gap_2_no_return", COUNT(DISTINCT CASE WHEN bucket = 'gap_3plus_returned' THEN rbuserid END) AS "gap_3plus_returned", COUNT(DISTINCT CASE WHEN bucket = 'gap_3plus_no_return' THEN rbuserid END) AS "gap_3plus_no_return", -- Sanity checks COUNT(DISTINCT CASE WHEN bucket = 'uncategorised' THEN rbuserid END) AS "uncategorised", COUNT(DISTINCT rbuserid) AS "total" FROM trip_buckets GROUP BY B ORDER BY "total" DESC;
